184     private void wakeConsumer() {
185         if(consuming.compareAndSet(false,true)) consumer.execute(()->{
186             try {
187                 if(reconciliation!=null) {
188                     Order unresolved=reconciliation;
189                     if(!orders.find(unresolved.id()).orElseThrow().terminal())
190                         completion.interrupt(unresolved.id(),unresolved.owner(),Instant.now(),"EXECUTION_INTERRUPTED");
191                     reconciliation=null;
192                 }
193                 while(!stopping) {
194                     Optional<Order> claimed=orders.claim(owner,Instant.now());
195                     if(claimed.isEmpty()) break;
196                     execute(claimed.orElseThrow());
197                 }
198                 synchronized(this) {
199                     imports.keySet().removeIf(id->orders.find(id).map(Order::terminal).orElse(true));
200                 }
201             } catch(RuntimeException failure) {runtimeReason="J3_EXECUTION_RECONCILIATION_REQUIRED";}
202             finally {consuming.set(false);}
203         });
204     }
