206     private void execute(Order order) {
207         reconciliation=order;
208         Standalone standalone=null;
209         var runtimeStop=new java.util.concurrent.atomic.AtomicReference<String>();
210         Thread watchdog=watch(order,runtimeStop);
211         Supplier<String> cancelled=()->runtimeStop.get()!=null?runtimeStop.get():stopping?"APPLICATION_STOPPED":
212                 order.automatic() && !orders.settings().enabled()?"AUTOMATION_DISABLED":null;
213         try {
214             if(order.trigger()==Trigger.MANUAL_IMPORT) {
215                 List<RawPayloadEvidence> pages;
216                 synchronized(this) {pages=imports.get(order.id());}
217                 if(pages==null) throw new IllegalStateException("J3_IMPORT_BYTES_UNAVAILABLE");
218                 engine.execute(order,null,pages,null,cancelled);
219             } else {
220                 var access=qualification.snapshot();
221                 if(!access.available()) throw new IllegalStateException(access.blockers().getFirst());
222                 var resource=reserveNetwork(order,access.providerOrigin(),cancelled);
223                 standalone=resource.standalone();
224                 if(resource.live()!=null) {
225                     // Work continues on the live owner, which retains its thread-affine lease.
226                     resource.live().get();
227                 } else {
228                     engine.execute(order,access.providerOrigin(),null,standalone,cancelled);
229                 }
230             }
231         } catch(AdmissionDeadlineExpired expired) {
232             // No collection or provider resource exists yet: only the claimed order ends.
233             if(!orders.find(order.id()).orElseThrow().terminal())
234                 orders.finish(order.id(),order.owner(),OrderState.CANCELLED,expired.getMessage(),Instant.now());
235         } catch(InterruptedException interrupted) {
236             Thread.currentThread().interrupt();runtimeReason="J3_INTERRUPTED";
237             if(!orders.find(order.id()).orElseThrow().terminal())
238                 completion.interrupt(order.id(),order.owner(),Instant.now(),"APPLICATION_STOPPED");
239         } catch(RuntimeException | ExecutionException failure) {
240             // Read after an uncertain commit; never retry provider work for the same order.
241             if(!orders.find(order.id()).orElseThrow().terminal())
242                 completion.interrupt(order.id(),order.owner(),Instant.now(),"EXECUTION_INTERRUPTED");
243         } finally {
244             watchdog.interrupt();
245             synchronized(this) {imports.remove(order.id());}
246             if(standalone!=null) finishStandalone(standalone);
247         }
248         reconciliation=null;
249     }
