251     private record Resource(Standalone standalone,CompletableFuture<J3CollectionExecutor.Result> live) { }
252     private static final class AdmissionDeadlineExpired extends RuntimeException {
253         AdmissionDeadlineExpired() {super("ADMISSION_DEADLINE_EXPIRED");}
254     }
255     private Resource reserveNetwork(Order order,java.net.URI origin,Supplier<String> cancelled) throws InterruptedException {
256         for(;;) {
257             String admissionStop=cancelled.get();
258             if("ADMISSION_DEADLINE_EXPIRED".equals(admissionStop)
259                     || admissionStop==null && !Instant.now().plusSeconds(130).isBefore(order.deadline()))
260                 throw new AdmissionDeadlineExpired();
261             if(admissionStop!=null) throw new PlaywrightDispatchCancelledException();
262             try {
263                 var handoff=live.submitJ3(order,(scope,liveCancellation)->engine.execute(order,origin,null,scope,
264                         ()->{String stopped=cancelled.get();return stopped!=null?stopped:liveCancellation.get();}));
265                 if(handoff.isPresent()) return new Resource(null,handoff.orElseThrow());
266                 // Atomic lease acquisition settles the race with a simultaneous live launch.
267                 var lease=coordinator.tryAcquireJ3Campaign(order.id());
268                 var standalone=new Standalone(order,cancelled);standalone.lease=lease;
269                 ownedStandaloneId=order.id();return new Resource(standalone,null);
270             } catch(ManualProviderRequestCoordinator.CoordinationException busy) {
271                 Thread.sleep(100);
272             } catch(IllegalStateException unavailable) {
273                 if(!"J3_LIVE_UNAVAILABLE".equals(unavailable.getMessage())) throw unavailable;
274                 Thread.sleep(100);
275             }
276         }
277     }
278 
279     private Thread watch(Order order,java.util.concurrent.atomic.AtomicReference<String> stopped) {
280         Instant wall=Instant.now();long start=System.nanoTime();
281         long remaining=Math.max(0,Duration.between(wall,order.deadline()).toNanos());
282         return Thread.ofPlatform().daemon(true).name("j3-deadline-watch").start(()->{
283             long before=start;Instant previous=wall;
284             while(!Thread.currentThread().isInterrupted()) {
285                 try {Thread.sleep(200);} catch(InterruptedException done) {Thread.currentThread().interrupt();return;}
286                 long now=System.nanoTime();Instant current=Instant.now();
287                 long elapsed=TimeUnit.NANOSECONDS.toMillis(now-before);
288                 if(elapsed>3000 || Math.abs(Duration.between(previous,current).toMillis()-elapsed)>2000
289                         || now-start>=remaining || !current.isBefore(order.deadline())) {
290                     stopped.set(now-start>=remaining?"ADMISSION_DEADLINE_EXPIRED":"APPLICATION_INTERRUPTED");
291                     if(order.id().equals(ownedStandaloneId))
292                         supervisor.stopCampaign(order.id(),Set.of(SofascoreEndpointType.SCHEDULED_EVENTS));
293                     return;
294                 }
295                 before=now;previous=current;
296             }
297         });
298     }
