  22     public record Proof(UUID runId, LocalDate date, Trigger trigger, Instant startedAt,
  23                         Instant finishedAt, State state, String terminalCode,
  24                         List<J3MinimizedPageEvidence> pages) {
  25         public Proof {
  26             Objects.requireNonNull(runId); Objects.requireNonNull(date); Objects.requireNonNull(trigger);
  27             Objects.requireNonNull(startedAt); Objects.requireNonNull(finishedAt); Objects.requireNonNull(state);
  28             pages = List.copyOf(pages);
  29             if (state == State.RUNNING || finishedAt.isBefore(startedAt) || pages.size() > 35
  30                     || terminalCode == null || !terminalCode.matches("[A-Z0-9_]{1,96}"))
  31                 throw new IllegalArgumentException("Invalid terminal J3 proof");
