  42     public static boolean complete(List<J3MinimizedPageEvidence> pages) {
  43         if (pages.isEmpty() || pages.size() > 35) return false;
  44         for (int i = 0; i < pages.size(); i++) {
  45             var p = pages.get(i);
  46             if (p.page() != i + 1 || !p.snapshotRecorded() || p.schemaStatus() != RawSnapshotSchemaStatus.PARSED
  47                     || p.httpStatus() < 200 || p.httpStatus() >= 300 || p.terminalCode() != null
  48                     || !Boolean.valueOf(i < pages.size() - 1).equals(p.hasNextPage())) return false;
  49         }
  50         return pages.stream().map(J3MinimizedPageEvidence::snapshotId).distinct().count() == pages.size();
  51     }
