 16 /** The singleton settings lock is also the J3 admission/configuration serialization boundary. */
 17 @Repository
 18 public class JdbcJ3AutomationStore implements J3AutomationStore {
 19     private final NamedParameterJdbcTemplate jdbc;
 20     private final J3CollectionStore collections;
 21     public JdbcJ3AutomationStore(NamedParameterJdbcTemplate jdbc,J3CollectionStore collections) {
 22         this.jdbc=jdbc;this.collections=collections;
 23     }
 24     @Override public Settings settings() {return readSettings(false);}
 25     private Settings readSettings(boolean lock) {
 26         if(lock)jdbc.queryForObject("select pg_advisory_xact_lock(-6060)",Map.of(),Object.class);
 27         return jdbc.queryForObject("select * from j3_automation_settings where singleton"+(lock?" for update":""),Map.of(),
 28                 (r,n)->new Settings(r.getBoolean("enabled"),Mode.valueOf(r.getString("daily_mode")),
 29                         r.getObject("daily_time",LocalTime.class),r.getLong("revision"),r.getTimestamp("updated_at").toInstant()));
 30     }
 31     @Override @Transactional public Settings configure(long revision,boolean enabled,Mode mode,LocalTime time,Instant now) {
 32         var before=readSettings(true);
 33         if(before.revision()!=revision)throw new IllegalStateException("J3_SETTINGS_CHANGED");
 34         var next=new Settings(enabled,mode,time,revision+1,now);
 35         if(!before.enabled() || !enabled) jdbc.update("""
 36             update j3_order set state='MISSED',finished_at=:now,reason='AUTOMATION_DISABLED'
 37             where state='FUTURE' and due_at<=:now
 38             """,Map.of("now",ts(now)));
 39         jdbc.update("""
 40             update j3_automation_settings set enabled=:enabled,daily_mode=:mode,daily_time=:time,revision=:revision,updated_at=:now
 41             where singleton
 42             """,new MapSqlParameterSource("enabled",enabled).addValue("mode",mode.name()).addValue("time",time)
 43                 .addValue("revision",next.revision()).addValue("now",ts(now)));
 44         if(!enabled) jdbc.update("""
 45             update j3_order set state='CANCELLED',finished_at=:now,reason='AUTOMATION_DISABLED'
 46             where state='QUEUED' and trigger_kind in ('DAILY','DAILY_AT','SCHEDULED')
 47             """,Map.of("now",ts(now)));
 48         // A revision may change its recurrence, but can never replay the old time.
 49         jdbc.update("""
 50             update j3_order set state='CANCELLED',finished_at=:now,reason='CONFIGURATION_CHANGED'
 51             where state='FUTURE' and trigger_kind='DAILY_AT'
 52             """,Map.of("now",ts(now)));
 53         return next;
 54     }
 55     @Override @Transactional public boolean lead(Owner owner,Predicate<Owner> isAlive) {
 56         readSettings(true);var current=currentLeader();
 57         if(current!=null && !current.id().equals(owner.id()) && isAlive.test(current))return false;
 58         jdbc.update("update j3_automation_settings set owner_id=:owner,owner_pid=:pid,owner_started_at=:processStart where singleton",owner(owner));
 59         return true;
 60     }
 61     @Override @Transactional public void release(Owner owner) {
 62         readSettings(true);
 63         jdbc.update("""
 64             update j3_automation_settings set owner_id=null,owner_pid=null,owner_started_at=null
 65             where singleton and owner_id=:owner
 66             """,owner(owner));
 67     }
 68     private Owner currentLeader() {
 69         return jdbc.queryForObject("select owner_id,owner_pid,owner_started_at from j3_automation_settings where singleton",Map.of(),
 70                 (r,n)->r.getObject(1)==null?null:new Owner(r.getObject(1,UUID.class),r.getLong(2),r.getTimestamp(3).toInstant()));
 71     }
 72     @Override @Transactional public Order schedule(UUID ruleId,int revision,LocalDate date,Instant dueAt,Instant now) {
 73         readSettings(true);
 74         if(ruleId==null || revision<1 || !dueAt.isAfter(now))throw new IllegalArgumentException("J3_PLAN_MUST_BE_FUTURE");
 75         String key="SCHEDULED|"+ruleId+"|"+revision;
 76         var duplicate=byKey(key);
 77         if(duplicate.isPresent()) {
 78             var existing=duplicate.orElseThrow();
 79             if(!existing.date().equals(date) || !existing.dueAt().equals(micros(dueAt)))throw new IllegalStateException("J3_PLAN_IDENTITY_CONFLICT");
 80             return existing;
 81         }
 82         var previous=jdbc.query("select * from j3_order where rule_id=:rule order by rule_revision desc limit 1",
 83                 Map.of("rule",ruleId),(r,n)->read(r));
 84         if(previous.isEmpty()?revision!=1:revision!=previous.getFirst().ruleRevision()+1)
 85             throw new IllegalStateException("J3_PLAN_REVISION_CONFLICT");
 86         if(!previous.isEmpty()) {
 87             var old=previous.getFirst();
 88             if(old.admittedAt()!=null)throw new IllegalStateException("J3_PLAN_ALREADY_ADMITTED");
 89             if(!old.terminal())terminal(old.id(),OrderState.CANCELLED,"PLAN_REVISED",now);
 90         }
 91         Integer count=jdbc.queryForObject("select count(*) from j3_order where trigger_kind='SCHEDULED' and state in ('FUTURE','QUEUED','RUNNING')",Map.of(),Integer.class);
 92         if(count>=MAXIMUM_PLANS)throw new IllegalStateException("J3_PLAN_LIMIT");
 93         UUID id=UUID.randomUUID();
 94         insert(id,key,ruleId,revision,date,Trigger.SCHEDULED,dueAt,now,null,null);
 95         return find(id).orElseThrow();
 96     }
 97     @Override @Transactional public void cancel(UUID id,Instant now) {
 98         readSettings(true);var order=find(id).orElseThrow();
 99         if(order.state()==OrderState.RUNNING)throw new IllegalStateException("J3_PLAN_ALREADY_ADMITTED");
100         if(!order.terminal())terminal(id,OrderState.CANCELLED,"OPERATOR_CANCELLED",now);
101     }
102     @Override @Transactional public Order manual(UUID id,LocalDate date,Trigger trigger,String hash,Owner owner,Instant now) {
103         readSettings(true);
104         if(trigger!=Trigger.MANUAL_PROVIDER && trigger!=Trigger.MANUAL_IMPORT)throw new IllegalArgumentException("J3_MANUAL_TRIGGER_REQUIRED");
105         var previous=find(id);
106         if(previous.isPresent()) {
107             var o=previous.orElseThrow();
108             if(!o.date().equals(date) || o.trigger()!=trigger || !Objects.equals(o.inputSha256(),hash))
109                 throw new IllegalStateException("J3_MANUAL_IDENTITY_CONFLICT");
110             return o;
111         }
112         insert(id,"MANUAL|"+id,null,0,date,trigger,now,now,owner,hash);
113         // Count before commit: a malicious or repeated form cannot create an unbounded execution queue.
114         Integer queued=jdbc.queryForObject("select count(*) from j3_order where state in ('QUEUED','RUNNING')",Map.of(),Integer.class);
115         if(queued>100)throw new IllegalStateException("J3_MANUAL_QUEUE_FULL");
116         return find(id).orElseThrow();
117     }
118     private void insert(UUID id,String key,UUID rule,int revision,LocalDate date,Trigger trigger,
119                         Instant due,Instant now,Owner owner,String hash) {
120         var p=new MapSqlParameterSource("id",id).addValue("key",key).addValue("rule",rule)
121                 .addValue("revision",rule==null?null:revision).addValue("date",date).addValue("trigger",trigger.name())
122                 .addValue("due",ts(due)).addValue("now",ts(now)).addValue("state",owner==null?"FUTURE":"QUEUED")
123                 .addValue("admitted",owner==null?null:ts(now)).addValue("deadline",owner==null?null:ts(now.plus(ORDER_DEADLINE)))
124                 .addValue("owner",owner==null?null:owner.id()).addValue("pid",owner==null?null:owner.pid())
125                 .addValue("processStart",owner==null?null:ts(owner.processStartedAt())).addValue("hash",hash);
126         jdbc.update("""
127             insert into j3_order(order_id,occurrence_key,rule_id,rule_revision,collection_date,trigger_kind,due_at,created_at,state,
128                 admitted_at,deadline,owner_id,owner_pid,owner_started_at,input_sha256)
129             values(:id,:key,:rule,:revision,:date,:trigger,:due,:now,:state,:admitted,:deadline,:owner,:pid,:processStart,:hash)
130             on conflict(occurrence_key) do nothing
131             """,p);
132     }
133     @Override @Transactional public void tick(Owner owner,Instant previousTick,Instant now,boolean continuous,String unavailable) {
134         Settings settings=readSettings(true);
135         if(!normalize(owner).equals(currentLeader()))throw new IllegalStateException("J3_SCHEDULER_NOT_OWNER");
136         LocalDate date=now.atZone(ZONE).toLocalDate();
137         if(settings.mode()==Mode.DAILY_AT) {
138             // Materialize absent days as missed evidence, in bounded batches after downtime.
139             // Past instants never become provider retries; due admission below still requires continuity.
140             LocalDate first=jdbc.queryForObject("""
141                     select coalesce(max(collection_date)+1,cast(:since as date)) from j3_order
142                     where trigger_kind='DAILY_AT' and occurrence_key like :prefix
143                     """,Map.of("since",settings.updatedAt().atZone(ZONE).toLocalDate(),
144                         "prefix","DAILY_AT|"+settings.revision()+"|%"),LocalDate.class);
145             for(int count=0;count<31 && !first.isAfter(date);count++,first=first.plusDays(1)) {
146                 String key=timedKey(settings,first);
147                 insert(UUID.randomUUID(),key,null,0,first,Trigger.DAILY_AT,
148                         dailyOccurrence(first,settings.dailyTime()),now,null,null);
149             }
150         }
151         var due=jdbc.query("select * from j3_order where state='FUTURE' and due_at<=:now order by due_at,order_id",
152                 Map.of("now",ts(now)),(r,n)->read(r));
153         boolean explicitToday=false;
154         for(var order:due) {
155             String missed=!settings.enabled()?"AUTOMATION_DISABLED":unavailable!=null?unavailable
156                     :!continuous || order.dueAt().isBefore(previousTick)?"LAB_NOT_IN_SERVICE":null;
157             if(missed!=null)terminal(order.id(),OrderState.MISSED,missed,now);
158             else {admit(order.id(),owner,now);if(order.date().equals(date))explicitToday=true;}
159         }
160         if(settings.enabled() && unavailable==null && settings.mode()==Mode.STARTUP_OR_DAY_CHANGE && byKey(dailyKey(date)).isEmpty()) {
161             UUID id=UUID.randomUUID();insert(id,dailyKey(date),null,0,date,Trigger.DAILY,now,now,owner,null);
162             if(collections.hasSuccess(date))terminal(id,OrderState.SKIPPED,"DATE_ALREADY_SUCCESSFUL",now);
163             else if(explicitToday)terminal(id,OrderState.SKIPPED,"EXPLICIT_OCCURRENCE_HAS_PRIORITY",now);
164         }
165     }
166     private void admit(UUID id,Owner owner,Instant now) {
167         jdbc.update("""
168             update j3_order set state='QUEUED',admitted_at=:now,deadline=:deadline,
169                 owner_id=:owner,owner_pid=:pid,owner_started_at=:processStart where order_id=:id and state='FUTURE'
170             """,owner(owner).addValue("now",ts(now)).addValue("deadline",ts(now.plus(ORDER_DEADLINE))).addValue("id",id));
171     }
172     @Override @Transactional public Optional<Order> claim(Owner owner,Instant now) {
173         Settings settings=readSettings(true);
174         if(Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from j3_order where state='RUNNING')",Map.of(),Boolean.class)))
175             return Optional.empty();
176         var queued=jdbc.query("select * from j3_order where state='QUEUED' and owner_id=:owner order by due_at,case when trigger_kind='DAILY' then 1 else 0 end,order_id",
177                 owner(owner),(r,n)->read(r));
178         for(var order:queued) {
179             if(!now.isBefore(order.deadline())) {terminal(order.id(),OrderState.MISSED,"ADMISSION_DEADLINE_EXPIRED",now);continue;}
180             if(order.automatic() && !settings.enabled()) {terminal(order.id(),OrderState.CANCELLED,"AUTOMATION_DISABLED",now);continue;}
181             if(order.trigger()==Trigger.DAILY && collections.hasSuccess(order.date())) {
182                 terminal(order.id(),OrderState.SKIPPED,"DATE_ALREADY_SUCCESSFUL",now);continue;
183             }
184             jdbc.update("update j3_order set state='RUNNING' where order_id=:id and state='QUEUED'",Map.of("id",order.id()));
185             return find(order.id());
186         }
187         return Optional.empty();
188     }
189     @Override @Transactional public void finish(UUID id,Owner owner,OrderState state,String reason,Instant now) {
190         readSettings(true);var order=find(id).orElseThrow();
191         if(order.owner()==null || !order.owner().equals(normalize(owner)))throw new IllegalStateException("J3_ORDER_NOT_OWNER");
192         if(order.terminal()) {
193             if(order.state()!=state || !Objects.equals(order.reason(),reason))throw new IllegalStateException("J3_ORDER_TERMINAL_CONFLICT");
194             return;
195         }
196         terminal(id,state,reason,now);
197     }
198     private void terminal(UUID id,OrderState state,String reason,Instant now) {
199         jdbc.update("update j3_order set state=:state,reason=:reason,finished_at=:now where order_id=:id",
200                 new MapSqlParameterSource("id",id).addValue("state",state.name()).addValue("reason",reason).addValue("now",ts(now)));
201     }
202     @Override public List<Order> recent(int limit) {
203         if(limit<1 || limit>1000)throw new IllegalArgumentException("J3_ORDER_LIST_LIMIT");
204         return jdbc.query("select * from j3_order order by created_at desc,order_id limit :limit",Map.of("limit",limit),(r,n)->read(r));
205     }
206     @Override public Optional<Order> find(UUID id) {
207         return jdbc.query("select * from j3_order where order_id=:id",Map.of("id",id),(r,n)->read(r)).stream().findFirst();
208     }
209     private Optional<Order> byKey(String key) {
210         return jdbc.query("select * from j3_order where occurrence_key=:key",Map.of("key",key),(r,n)->read(r)).stream().findFirst();
211     }
212     @Override public List<Order> interrupted(Owner current) {
213         return jdbc.query("select * from j3_order where state in ('QUEUED','RUNNING') and owner_id<>:owner order by due_at,order_id",
214                 owner(current),(r,n)->read(r));
215     }
216     private static Order read(ResultSet r)throws SQLException {
217         UUID owner=r.getObject("owner_id",UUID.class);
218         return new Order(r.getObject("order_id",UUID.class),r.getString("occurrence_key"),r.getObject("rule_id",UUID.class),
219                 r.getInt("rule_revision"),r.getObject("collection_date",LocalDate.class),Trigger.valueOf(r.getString("trigger_kind")),
220                 instant(r,"due_at"),instant(r,"created_at"),OrderState.valueOf(r.getString("state")),instant(r,"admitted_at"),
221                 instant(r,"deadline"),instant(r,"finished_at"),r.getString("reason"),owner==null?null:
222                 new Owner(owner,r.getLong("owner_pid"),instant(r,"owner_started_at")),r.getString("input_sha256"));
223     }
224     private static MapSqlParameterSource owner(Owner owner) {
225         return new MapSqlParameterSource("owner",owner.id()).addValue("pid",owner.pid()).addValue("processStart",ts(owner.processStartedAt()));
226     }
227     private static Owner normalize(Owner o) {return new Owner(o.id(),o.pid(),micros(o.processStartedAt()));}
228     private static Instant instant(ResultSet row,String column)throws SQLException {var value=row.getTimestamp(column);return value==null?null:value.toInstant();}
229     private static Instant micros(Instant value) {return value.truncatedTo(java.time.temporal.ChronoUnit.MICROS);}
230     private static Timestamp ts(Instant value) {return Timestamp.from(micros(value));}
231 }

