121     @Override @Transactional
122     public void interrupt(UUID id,Instant now,String reason) {
123         jdbc.queryForObject("select pg_advisory_xact_lock(-6060)",java.util.Map.of(),Object.class);
124         var rows=jdbc.queryForList("select * from j3_collection_run where run_id=:id for update",params(id));
125         if(rows.isEmpty() || !"RUNNING".equals(rows.getFirst().get("state"))) return;
126         var row=rows.getFirst();
127         var pages=jdbc.query("select evidence::text from j3_collection_page where run_id=:id order by page",params(id),
128                 (r,n)->JSON.readValue(r.getString(1),J3MinimizedPageEvidence.class));
129         Instant start=((java.sql.Timestamp)row.get("started_at")).toInstant();
130         publish(new Proof(id,((java.sql.Date)row.get("collection_date")).toLocalDate(),
131                 Trigger.valueOf((String)row.get("trigger_kind")),start,now.isBefore(start)?start:now,
132                 State.INTERRUPTED,reason,pages),java.util.List.of());
133     }
134     private Collection read(ResultSet rs) throws SQLException {
135         UUID id = rs.getObject("run_id", UUID.class);
136         var pages = jdbc.query("select evidence::text from j3_collection_page where run_id=:id order by page", params(id),
137                 (r,n) -> JSON.readValue(r.getString(1), J3MinimizedPageEvidence.class));
138         var entries = jdbc.query("""
139                 select entry::text from j3_catalog_entry where run_id=:id
140                 order by entry->>'category' collate "C",entry->>'name' collate "C",tournament_id
141                 """, params(id), (r,n) -> JSON.readValue(r.getString(1), Entry.class));
142         return new Collection(new Proof(id, rs.getObject("collection_date", LocalDate.class),
143                 Trigger.valueOf(rs.getString("trigger_kind")), rs.getTimestamp("started_at").toInstant(),
144                 rs.getTimestamp("finished_at").toInstant(), State.valueOf(rs.getString("state")),
145                 rs.getString("terminal_code"), pages), entries);
146     }
