  18 
  19 /** Shared J3/J4/J5 refusal and departure admission. Never opens or retries a session itself. */
  20 @Primary @Component
  21 public final class ResilientPlaywrightProviderCampaignFactory implements PlaywrightProviderCampaignFactory {
  22     private final PlaywrightProviderCampaignFactory delegate;
  23     private final ProviderResilienceStore store;
  24     private final Clock clock;
  25     private final Pause pause;
  26     // Keep a refusal blocking even if its SQL acknowledgement fails. Closing retries only local persistence.
  27     private final AtomicReference<Refusal> pendingRefusal = new AtomicReference<>();
  28     private record Refusal(UUID evidenceId, UUID campaignId, int status, Instant at, Instant retryAt) { }
  29     @FunctionalInterface interface Pause { void sleep(Duration duration) throws InterruptedException; }
  30 
  31     @Autowired
  32     public ResilientPlaywrightProviderCampaignFactory(ChildJvmPlaywrightProviderSupervisor delegate,
  33                                                       ProviderResilienceStore store) {
  34         this(delegate,store,Clock.systemUTC(),d -> Thread.sleep(d));
  35     }
  36 
  37     ResilientPlaywrightProviderCampaignFactory(PlaywrightProviderCampaignFactory delegate,
  38                                               ProviderResilienceStore store, Clock clock, Pause pause) {
  39         this.delegate=delegate; this.store=store; this.clock=clock; this.pause=pause;
  40     }
  41 
  42     @Override public PlaywrightProviderCampaign open(UUID id, Set<SofascoreEndpointType> endpoints) {
  43         return openProtected(id,()->delegate.open(id,endpoints));
  44     }
  45     @Override public PlaywrightProviderCampaign openLiveGrouped(UUID id, Set<SofascoreEndpointType> endpoints) {
  46         return openProtected(id,()->delegate.openLiveGrouped(id,endpoints));
  47     }
  48     @Override public PlaywrightProviderCampaign openLiveGroupedV5(UUID id, Set<SofascoreEndpointType> endpoints) {
  49         return openProtected(id,()->delegate.openLiveGroupedV5(id,endpoints));
  50     }
  51     @Override public PlaywrightProviderCampaign openLiveGroupedV6(UUID id, Set<SofascoreEndpointType> endpoints) {
  52         return openProtected(id,()->delegate.openLiveGroupedV6(id,endpoints),true,DepartureProfile.LEGACY_V1);
  53     }
  54     @Override public PlaywrightProviderCampaign openLiveGroupedV7(UUID id, Set<SofascoreEndpointType> endpoints) {
  55         return openProtected(id,()->delegate.openLiveGroupedV7(id,endpoints),true,DepartureProfile.LEGACY_V1);
  56     }
  57     @Override public PlaywrightProviderCampaign openLiveGroupedV8(UUID id, Set<SofascoreEndpointType> endpoints) {
  58         return openProtected(id,()->delegate.openLiveGroupedV8(id,endpoints),true,DepartureProfile.LIVE_V8);
  59     }
  60     @Override public PlaywrightProviderCampaign openLiveGroupedV9(UUID id, Set<SofascoreEndpointType> endpoints) {
