  63         return openProtected(id,()->delegate.openLiveGroupedV9(id,endpoints),true,DepartureProfile.LIVE_V8);
  64     }
  65     @Override public PlaywrightProviderCampaign openLiveGroupedV10(UUID id, Set<SofascoreEndpointType> endpoints) {
  66         return openProtected(id,()->delegate.openLiveGroupedV10(id,endpoints),true,DepartureProfile.LIVE_V10);
  67     }
  68     @Override public PlaywrightProviderCampaign openLiveGroupedV11(UUID id, Set<SofascoreEndpointType> endpoints) {
