  70     }
  71     @Override public PlaywrightProviderCampaign openManualJ5Grouped(UUID id, Set<SofascoreEndpointType> endpoints) {
  72         return openProtected(id,()->delegate.openManualJ5Grouped(id,endpoints));
  73     }
  74 
  75     private void requireOpen() {
  76         if(pendingRefusal.get()!=null || store.snapshot().state()==State.SUSPENDED)
  77             throw new IllegalStateException("PROVIDER_SUSPENDED");
  78     }
  79 
  80     private PlaywrightProviderCampaign openProtected(UUID campaignId, Supplier<PlaywrightProviderCampaign> opening) {
  81         return openProtected(campaignId, opening, false, DepartureProfile.LEGACY_V1);
  82     }
  83 
  84     private PlaywrightProviderCampaign openProtected(UUID campaignId, Supplier<PlaywrightProviderCampaign> opening,
  85                                                      boolean recoverTimeouts) {
  86         return openProtected(campaignId, opening, recoverTimeouts, DepartureProfile.LEGACY_V1);
  87     }
  88 
  89     private PlaywrightProviderCampaign openProtected(UUID campaignId, Supplier<PlaywrightProviderCampaign> opening,
  90                                                      boolean recoverTimeouts, DepartureProfile departureProfile) {
  91         requireOpen();
  92         if(store.snapshot().unresolvedDispatchId()!=null) throw new IllegalStateException("PROVIDER_DEPARTURE_UNRESOLVED");
  93         PlaywrightProviderCampaign campaign=opening.get();
  94         return new PlaywrightProviderCampaign() {
  95             private UUID unfinished;
  96             @Override public PlaywrightProviderCampaign openJ3SubOperation(J3ProviderSubOperation scope) {
  97                 requireOpen();
  98                 if(unfinished!=null)throw new IllegalStateException("PROVIDER_DEPARTURE_UNRESOLVED");
  99                 // The same durable counter charges J3 under its original, more restrictive pressure profile.
 100                 return openProtected(scope.runId(),()->campaign.openJ3SubOperation(scope),false,DepartureProfile.LEGACY_V1);
 101             }
 102             @Override public PlaywrightProviderResponse execute(PlaywrightProviderRequest request) {
 103                 return execute(request,PlaywrightDispatchAdmission.UNRESTRICTED);
 104             }
 105             @Override public PlaywrightProviderResponse execute(PlaywrightProviderRequest request,
 106                                                                 PlaywrightDispatchAdmission admission) {
 107                 return dispatch(request,null,admission);
 108             }
 109             @Override public PlaywrightProviderResponse executeGrouped(PlaywrightProviderRequest request,
 110                     LiveProviderDispatchGroup group, PlaywrightDispatchAdmission admission) {
 111                 return dispatch(request,group,admission);
 112             }
 113             private PlaywrightProviderResponse dispatch(PlaywrightProviderRequest request,
 114                     LiveProviderDispatchGroup group, PlaywrightDispatchAdmission admission) {
 115                 requireOpen(); UUID dispatchId=UUID.randomUUID();
 116                 AtomicReference<Refusal> refusal=new AtomicReference<>();
 117                 var protectedAdmission=new PlaywrightDispatchAdmission() {
 118                     @Override public void check() { admission.check(); requireOpen(); }
 119                     @Override public Permit acquireDispatchPermit() {
 120                         // The underlying supervisor holds single-flight. No SQL lock survives this method.
 121                         awaitReservation(dispatchId,admission,departureProfile);
 122                         unfinished=dispatchId;
 123                         // Reservation remains charged on cancellation/failure: no duplicate emission is inferred.
 124                         return admission.acquireDispatchPermit();
 125                     }
 126                     @Override public void onTransportProgress(PlaywrightTransportDiagnostic diagnostic) {
 127                         RuntimeException refusalFailure = null;
 128                         try {
 129                             // A known refusal remains first: an incoherent worker timestamp
 130                             // can stop V8, but must never discard a 403/429 suspension.
 131                             observeRefusal(diagnostic,dispatchId,campaignId,refusal);
 132                             recordAuthenticatedDeparture(dispatchId,departureProfile,
 133                                     diagnostic == null ? null : diagnostic.requestedAt(),clock.instant());
 134                         }
 135                         catch (RuntimeException failure) { refusalFailure = failure; }
 136                         // Even when the refusal transaction fails, retain the known headers in the
 137                         // campaign diagnosis. Neither failure authorizes continued transport.
 138                         try { admission.onTransportProgress(diagnostic); }
 139                         catch (RuntimeException diagnosticFailure) {
 140                             if (refusalFailure == null) throw diagnosticFailure;
 141                         }
 142                         if (refusalFailure != null) throw refusalFailure;
 143                     }
 144                 };
 145                 try {
 146                     var response=group==null ? campaign.execute(request,protectedAdmission)
 147                             : campaign.executeGrouped(request,group,protectedAdmission);
 148                     observeRefusal(response.diagnostic(),dispatchId,campaignId,refusal);
 149                     if((response.httpStatus()==403 || response.httpStatus()==429) && refusal.get()==null)
 150                         persistRefusal(new Refusal(dispatchId,campaignId,response.httpStatus(),response.receivedAt(),null));
 151                     // A completed response is an idempotent fallback for transports that
 152                     // cannot stream REQUEST_SENT progress.  Its constructor already proves
 153                     // requestedAt <= receivedAt; the store also checks the active reservation.
 154                     recordAuthenticatedDeparture(dispatchId,departureProfile,response.requestedAt(),response.receivedAt());
 155                     finishDeparture();
 156                     return response;
 157                 } catch(PlaywrightProviderException failure) {
 158                     observeRefusal(failure.diagnostic(),dispatchId,campaignId,refusal);
 159                     recordAuthenticatedDeparture(dispatchId,departureProfile,
 160                             failure.diagnostic()==null?null:failure.diagnostic().requestedAt(),clock.instant());
 161                     // The terminal acknowledgement includes verified page/context cleanup.
 162                     // Persist the charge's end before the caller may defer or emit again.
 163                     if (recoverTimeouts && failure.recoverableTimeout()) {
 164                         admission.onTransportProgress(failure.diagnostic());
 165                         finishDeparture();
 166                     }
 167                     throw failure;
 168                 }
 169             }
 170             @Override public void close() {
 171                 // Close processes first. A refusal must be durable before the pressure reservation
 172                 // is released, otherwise restarting the JVM could discard the only blocking proof.
 173                 campaign.close();
 174                 flushPendingRefusal();
 175                 finishDeparture();
 176             }
 177             private void finishDeparture() {
 178                 if(unfinished!=null) { store.markDepartureFinished(unfinished,clock.instant()); unfinished=null; }
 179             }
 180         };
 181     }
 182 
 183     private void awaitReservation(UUID dispatchId, PlaywrightDispatchAdmission admission, DepartureProfile departureProfile) {
 184         while(true) {
 185             admission.check(); requireOpen();
 186             // Preserve the legacy method path for pre-V8 callers. This keeps their durable
 187             // contract unchanged while V8 explicitly selects its faster local envelope.
 188             var decision=departureProfile==DepartureProfile.LEGACY_V1
 189                     ? store.tryReserveDeparture(dispatchId,clock.instant())
 190                     : store.tryReserveDeparture(dispatchId,departureProfile,clock.instant());
 191             if(decision.allowed()) return;
 192             if(decision.reason()!=DepartureReason.RATE_LIMITED && decision.reason()!=DepartureReason.POST_EXCHANGE_FENCE)
 193                 throw new IllegalStateException(decision.reason()==DepartureReason.PROVIDER_SUSPENDED
 194                         ? "PROVIDER_SUSPENDED" : decision.reason()==DepartureReason.DEPARTURE_UNRESOLVED
 195                         ? "PROVIDER_DEPARTURE_UNRESOLVED" : "PROVIDER_CLOCK_REGRESSION");
 196             Instant until=decision.nextAllowedAt();
 197             while(clock.instant().isBefore(until)) {
 198                 admission.check();
 199                 if(pendingRefusal.get()!=null) throw new IllegalStateException("PROVIDER_SUSPENDED");
 200                 Duration remaining=Duration.between(clock.instant(),until);
 201                 if(remaining.isNegative() || remaining.isZero()) break;
 202                 try { pause.sleep(remaining.compareTo(Duration.ofMillis(50))>0?Duration.ofMillis(50):remaining); }
 203                 catch(InterruptedException interrupted) {
 204                     Thread.currentThread().interrupt(); throw new PlaywrightDispatchCancelledException();
 205                 }
 206             }
 207         }
 208     }
 209 
 210     private void observeRefusal(PlaywrightTransportDiagnostic d, UUID dispatchId, UUID campaignId,
 211                                AtomicReference<Refusal> observed) {
 212         if(d==null || d.httpStatus()==null || (d.httpStatus()!=403 && d.httpStatus()!=429)) return;
 213         Refusal evidence=new Refusal(dispatchId,campaignId,d.httpStatus(),
 214                 d.headersReceivedAt()==null?clock.instant():d.headersReceivedAt(),d.retryAfterNotBefore());
 215         if(observed.compareAndSet(null,evidence)) persistRefusal(evidence);
 216     }
 217     /** Authenticated worker evidence is accepted only for explicitly qualified profiles. */
 218     private void recordAuthenticatedDeparture(UUID dispatchId, DepartureProfile profile,
 219                                              Instant requestedAt, Instant observedAt) {
 220         if ((profile != DepartureProfile.LIVE_V8 && profile != DepartureProfile.LIVE_V10) || requestedAt == null) return;
 221         if (observedAt == null || requestedAt.isAfter(observedAt))
 222             throw new IllegalStateException("PROVIDER_REQUESTED_TIMESTAMP_INCOHERENT");
 223         if (profile == DepartureProfile.LIVE_V10) store.recordAuthenticatedV10Departure(dispatchId,requestedAt,observedAt);
 224         else store.recordAuthenticatedV8Departure(dispatchId,requestedAt,observedAt);
 225     }
 226     private void persistRefusal(Refusal refusal) {
 227         pendingRefusal.compareAndSet(null,refusal);
 228         store.suspend(refusal.evidenceId(),refusal.campaignId(),refusal.status(),refusal.at(),refusal.retryAt());
 229         pendingRefusal.compareAndSet(refusal,null);
 230     }
 231     private void flushPendingRefusal() {
 232         Refusal pending=pendingRefusal.get();
 233         if(pending!=null) persistRefusal(pending);
 234     }
 235 }

