 294         StopTombstones tombstones = stopTombstonesFor(allowlist);
 295         if (tombstones.blocks(campaignId)) {
 296             throw new PlaywrightProviderException(PlaywrightProviderFailure.OPERATOR_STOP);
 297         }
 298         Path workerJar = requireWorkerJar();
