 300         if (!active.compareAndSet(null, state)) {
 301             throw new PlaywrightProviderException(
 302                     PlaywrightProviderFailure.CAMPAIGN_ALREADY_ACTIVE);
 303         }
 304         try {
 305             requireStartupAllowed(state, tombstones, campaignId);
 306             ServerSocket server = openLoopbackServer();
 307             state.server = server;
 308             requireStartupAllowed(state, tombstones, campaignId);
 309             String token = newToken();
 310             requireStartupAllowed(state, tombstones, campaignId);
 311             Process process = startWorker(workerJar, server.getLocalPort(), token);
 312             Instant processStartedAt = process.info().startInstant().orElse(null);
 313             state.publishProcess(process, processStartedAt);
 314             if (processStartedAt == null) {
 315                 process.destroyForcibly();
 316                 throw new PlaywrightProviderException(
 317                         PlaywrightProviderFailure.RUNTIME_FAILURE);
 318             }
 319             requireStartupAllowed(state, tombstones, campaignId);
 320 
 321             Socket socket = server.accept();
 322             requireStartupAllowed(state, tombstones, campaignId);
 323             requireExactLoopbackPeer(socket);
 324             socket.setTcpNoDelay(true);
 325             socket.setKeepAlive(false);
 326             socket.setSoTimeout(toMillis(properties.getStartupTimeout()));
 327             DataInputStream input = new DataInputStream(
 328                     new BufferedInputStream(socket.getInputStream()));
 329             DataOutputStream output = new DataOutputStream(
 330                     new BufferedOutputStream(socket.getOutputStream()));
