 332             authenticate(input, token);
 333             requireStartupAllowed(state, tombstones, campaignId);
 334             startWorkerRuntime(input, output,state.j3PauseCapable);
 335             requireStartupAllowed(state, tombstones, campaignId);
 336             ProcessRegistration registration = state.processRegistration.getNow(null);
 337             ProcessTreeSnapshot initialInventory = captureInitialProcessInventory(
 338                     state,
 339                     Objects.requireNonNull(registration, "process registration"));
 340             if (!initialInventory.isExactFor(registration)) {
 341                 throw new PlaywrightProviderException(
 342                         PlaywrightProviderFailure.RUNTIME_FAILURE);
 343             }
