  14 /** One explicitly opened context for exactly the four existing event endpoints. */
  15 public final class LiveProviderSession implements AutoCloseable {
  16     public static final Set<SofascoreEndpointType> ENDPOINTS = Set.of(
  17             SofascoreEndpointType.EVENT_DETAILS, SofascoreEndpointType.EVENT_STATISTICS,
  18             SofascoreEndpointType.EVENT_INCIDENTS, SofascoreEndpointType.EVENT_LINEUPS);
  19     private final PlaywrightProviderCampaign campaign;
  20     private final boolean conditionalRevalidation;
  21     /**
  22      * Ephemeral, campaign-local validators.  They are deliberately neither read from nor written
  23      * to the durable payload cache: a fresh Playwright context starts with no conditional state.
  24      */
  25     private final Map<ConditionalKey, CachedValidator> validators = new ConcurrentHashMap<>();
  26     /** The exact validator supplied on an in-flight request, used to reject an uncorrelated 304. */
  27     private final Map<ConditionalKey, PlaywrightProviderEntityTag> dispatchedValidators = new ConcurrentHashMap<>();
  28 
  29     public LiveProviderSession(PlaywrightProviderCampaignFactory factory, UUID campaignId) {
  30         this(factory, campaignId, "live-v3");
  31     }
  32     public LiveProviderSession(PlaywrightProviderCampaignFactory factory, UUID campaignId, String policyVersion) {
  33         conditionalRevalidation = "live-v9".equals(policyVersion) || "live-v10".equals(policyVersion) || "live-v11".equals(policyVersion);
  34         campaign = switch (policyVersion) {
  35             case "live-v11" -> factory.openLiveGroupedV11(campaignId, ENDPOINTS);
  36             case "live-v10" -> factory.openLiveGroupedV10(campaignId, ENDPOINTS);
  37             case "live-v9" -> factory.openLiveGroupedV9(campaignId, ENDPOINTS);
  38             case "live-v8" -> factory.openLiveGroupedV8(campaignId, ENDPOINTS);
  39             case "live-v7" -> factory.openLiveGroupedV7(campaignId, ENDPOINTS);
  40             case "live-v6" -> factory.openLiveGroupedV6(campaignId, ENDPOINTS);
  41             case "live-v5" -> factory.openLiveGroupedV5(campaignId, ENDPOINTS);
  42             case "live-v4" -> factory.openLiveGrouped(campaignId, ENDPOINTS);
  43             case null, default -> factory.open(campaignId, ENDPOINTS);
  44         };
  45     }
  46     public PlaywrightProviderResponse execute(long providerId, SofascoreEndpointType endpoint,
  47                                                PlaywrightDispatchAdmission admission) {
  48         return campaign.execute(request(providerId, endpoint), admission);
  49     }
  50     public PlaywrightProviderResponse executeGrouped(long providerId, SofascoreEndpointType endpoint,
  51             LiveProviderDispatchGroup group, PlaywrightDispatchAdmission admission) {
  52         return campaign.executeGrouped(request(providerId, endpoint), group, admission);
  53     }
  54 
  55     /**
  56      * Returns the exact previously accepted facts only after a correlated V9/V10 304.  No provider
  57      * response body, raw snapshot, normalized observation, or persisted cache entry is created by
  58      * this method.  The caller must publish its ledger result before {@link #acceptNotModified}.
  59      */
  60     Optional<RevalidatedExchange> revalidated(long providerId, SofascoreEndpointType endpoint,
  61                                               PlaywrightProviderResponse response) {
  62         Objects.requireNonNull(response, "response");
  63         ConditionalKey key = key(providerId, endpoint);
  64         PlaywrightProviderEntityTag sent = dispatchedValidators.remove(key);
  65         if (!conditionalRevalidation || response.httpStatus() != 304 || sent == null) {
  66             return Optional.empty();
  67         }
  68         CachedValidator cached = validators.get(key);
  69         if (cached == null || !cached.entityTag().equals(sent)) {
  70             return Optional.empty();
  71         }
  72         return Optional.of(new RevalidatedExchange(key, cached, response.entityTag()));
  73     }
  74 
  75     /**
  76      * Records a validator only after its 2xx response was parsed and its normalized result was
  77      * committed.  A 2xx response without an entity tag deliberately removes the prior validator.
  78      */
  79     void retainParsed(long providerId, SofascoreEndpointType endpoint,
  80                       PlaywrightProviderResponse response, ScheduleFacts facts) {
  81         Objects.requireNonNull(response, "response");
  82         Objects.requireNonNull(facts, "facts");
  83         ConditionalKey key = key(providerId, endpoint);
  84         dispatchedValidators.remove(key);
  85         if (!conditionalRevalidation || response.httpStatus() < 200 || response.httpStatus() >= 300
  86                 || response.entityTag().isEmpty()) {
  87             validators.remove(key);
  88             return;
  89         }
  90         validators.put(key, new CachedValidator(response.entityTag().orElseThrow(), facts));
  91     }
  92 
  93     /**
  94      * Commits the harmless in-memory validator refresh from a correlated 304 only after the
  95      * caller has appended the corresponding non-success ledger result.
  96      */
  97     void acceptNotModified(RevalidatedExchange exchange) {
  98         Objects.requireNonNull(exchange, "exchange");
  99         if (!conditionalRevalidation) {
 100             throw new IllegalStateException("conditional revalidation is unavailable for this live policy");
 101         }
 102         CachedValidator current = validators.get(exchange.key);
 103         if (current == null || !current.entityTag().equals(exchange.cached.entityTag())) {
 104             throw new IllegalStateException("conditional validator changed before publication");
 105         }
 106         PlaywrightProviderEntityTag validator = exchange.responseEntityTag.orElse(current.entityTag());
 107         validators.put(exchange.key, new CachedValidator(validator, current.facts()));
 108     }
 109 
 110     /** Fails closed: no uncommitted or failed exchange may be used to condition a later request. */
 111     void discardConditionalState(long providerId, SofascoreEndpointType endpoint) {
 112         ConditionalKey key = key(providerId, endpoint);
 113         dispatchedValidators.remove(key);
 114         validators.remove(key);
 115     }
