 117     private PlaywrightProviderRequest request(long providerId, SofascoreEndpointType endpoint) {
 118         ConditionalKey key = key(providerId, endpoint);
 119         PlaywrightProviderRequest request = new PlaywrightProviderRequest(endpoint, null, 0, 0, providerId);
 120         if (!conditionalRevalidation) {
 121             return request;
 122         }
 123         CachedValidator cached = validators.get(key);
 124         if (cached == null) {
 125             dispatchedValidators.remove(key);
 126             return request;
 127         }
 128         dispatchedValidators.put(key, cached.entityTag());
 129         return request.withIfNoneMatch(cached.entityTag());
 130     }
 131 
 132     private static ConditionalKey key(long providerId, SofascoreEndpointType endpoint) {
 133         if (providerId < 1 || !ENDPOINTS.contains(endpoint)) {
 134             throw new IllegalArgumentException("endpoint outside live scope");
 135         }
 136         return new ConditionalKey(providerId, endpoint);
 137     }
