 139     public PlaywrightProviderCampaign openJ3SubOperation(J3ProviderSubOperation scope) {
 140         dispatchedValidators.clear();
 141         return campaign.openJ3SubOperation(scope);
 142     }
 143 
 144     @Override public void close() {
 145         dispatchedValidators.clear();
 146         validators.clear();
 147         campaign.close();
 148     }
