 150     /** Facts already accepted from the exact endpoint in this active local campaign. */
 151     record ScheduleFacts(String sportStatus, Map<String, Boolean> signals, Instant scheduledKickoff,
 152                          Boolean lineupsConfirmed, LiveJ4ControlFacts j4Controls) {
 153         public ScheduleFacts {
 154             signals = Map.copyOf(Objects.requireNonNull(signals, "signals"));
 155         }
 156     }
 157 
 158     /** Opaque proof that a 304 was correlated with the exact volatile validator that was sent. */
 159     static final class RevalidatedExchange {
 160         private final ConditionalKey key;
 161         private final CachedValidator cached;
 162         private final Optional<PlaywrightProviderEntityTag> responseEntityTag;
 163 
 164         private RevalidatedExchange(ConditionalKey key, CachedValidator cached,
 165                                     Optional<PlaywrightProviderEntityTag> responseEntityTag) {
 166             this.key = Objects.requireNonNull(key, "key");
 167             this.cached = Objects.requireNonNull(cached, "cached");
 168             this.responseEntityTag = Objects.requireNonNull(responseEntityTag, "responseEntityTag");
 169         }
 170 
 171         ScheduleFacts facts() {
 172             return cached.facts();
 173         }
 174     }
 175 
 176     private record ConditionalKey(long providerId, SofascoreEndpointType endpoint) { }
 177     private record CachedValidator(PlaywrightProviderEntityTag entityTag, ScheduleFacts facts) {
 178         private CachedValidator {
 179             Objects.requireNonNull(entityTag, "entityTag");
 180             Objects.requireNonNull(facts, "facts");
 181         }
 182     }
