   9 class J3WorkerScopeProtocolTest {
  10     static final Instant NOW=Instant.parse("2026-09-13T12:00:00Z");
  11     @Test void startCapabilityIsExplicitAndHistoricalStartDoesNotGrantIt() throws Exception {
  12         assertThat(ProviderPlaywrightWorkerProtocol.requireStart(input(new byte[]{ProviderPlaywrightWorkerProtocol.START}))).isFalse();
  13         assertThat(ProviderPlaywrightWorkerProtocol.requireStart(input(new byte[]{ProviderPlaywrightWorkerProtocol.START_WITH_J3_PAUSE}))).isTrue();
  14     }
  15     @Test void scopeKeepsExactIdentityDateAndDeadline() throws Exception {
  16         UUID id=UUID.randomUUID();Instant deadline=NOW.plusSeconds(1199);
  17         var scope=ProviderPlaywrightWorkerProtocol.readJ3Scope(scope(id.toString(),"2026-09-14",deadline),NOW);
  18         assertThat(scope.runId()).isEqualTo(id);assertThat(scope.date()).isEqualTo(LocalDate.parse("2026-09-14"));
  19         assertThat(scope.deadline()).isEqualTo(deadline);
  20     }
  21     @Test void expiredOrExtendedScopesAndNonCanonicalIdentifiersAreRejected() {
  22         for(var deadline:new Instant[]{NOW,NOW.minusSeconds(1),NOW.plusSeconds(1201)})
  23             assertThatThrownBy(()->ProviderPlaywrightWorkerProtocol.readJ3Scope(scope(UUID.randomUUID().toString(),"2026-09-14",deadline),NOW))
  24                     .isInstanceOf(ProviderPlaywrightWorkerProtocol.ProtocolValidationException.class);
  25         assertThatThrownBy(()->ProviderPlaywrightWorkerProtocol.readJ3Scope(scope("1-1-1-1-1","2026-09-14",NOW.plusSeconds(10)),NOW))
  26                 .isInstanceOf(ProviderPlaywrightWorkerProtocol.ProtocolValidationException.class);
  27         assertThatThrownBy(()->ProviderPlaywrightWorkerProtocol.readJ3Scope(scope(UUID.randomUUID().toString(),"2026-02-30",NOW.plusSeconds(10)),NOW))
  28                 .isInstanceOf(ProviderPlaywrightWorkerProtocol.ProtocolValidationException.class);
  29     }
  30     static DataInputStream scope(String id,String date,Instant deadline)throws IOException {
  31         var bytes=new ByteArrayOutputStream();try(var out=new DataOutputStream(bytes)){out.writeUTF(id);out.writeUTF(date);out.writeLong(deadline.toEpochMilli());}
  32         return input(bytes.toByteArray());
  33     }
  34     static DataInputStream input(byte[] bytes){return new DataInputStream(new ByteArrayInputStream(bytes));}
  35 }
