 865     private void terminateSynchronously(CampaignState state, boolean requestGracefulClose) {
 866         state.requestTermination(processTreeAccess);
 867         long terminationStartedAt = state.markTerminationStarted(processTreeAccess);
 868         synchronized (state.cleanupLock) {
 869             if (state.cleanupCompleted) {
 870                 return;
 871             }
 872             if (state.cleanupTerminalFailure != null) {
 873                 throw state.cleanupTerminalFailure;
 874             }
 875             boolean gracefulAttempt = requestGracefulClose
 876                     && !state.operatorStopRequested.get();
 877             long cleanupStartedAt = gracefulAttempt
 878                     ? processTreeAccess.nanoTime()
 879                     : state.operatorStopStartedAtOr(terminationStartedAt);
 880             AtomicBoolean mutationStarted = new AtomicBoolean();
 881             Throwable cleanupFailure = null;
 882             try {
 883                 ProcessRegistration registration = awaitProcessRegistration(
 884                         state,
 885                         cleanupStartedAt);
 886                 state.phase.set(CampaignPhase.TERMINATING);
 887                 if (registration.processLaunched()) {
 888                     if (!registration.identityComplete()) {
 889                         mutationStarted.set(true);
 890                         registration.process().destroyForcibly();
 891                         throw new PlaywrightProviderException(
 892                                 PlaywrightProviderFailure.RUNTIME_FAILURE);
 893                     }
 894                     ProcessTreeSnapshot initialInventory = captureInitialProcessInventory(
 895                             state,
 896                             registration);
 897                     boolean authenticatedWorkerExitExpected =
 898                             state.authenticatedTerminalFrameReceived.get();
 899                     ProcessTreeSnapshot terminationInventory = captureTerminationProcessInventory(
 900                             registration,
 901                             initialInventory,
 902                             authenticatedWorkerExitExpected);
 903                     boolean gracefulCloseMode = gracefulAttempt;
 904                     boolean closeAcknowledged = false;
 905                     boolean parentTerminationSignalled = false;
 906                     if (gracefulCloseMode) {
 907                         closeAcknowledged = requestClose(
 908                                 state,
 909                                 mutationStarted,
 910                                 cleanupStartedAt);
 911                         authenticatedWorkerExitExpected |= closeAcknowledged;
 912                         terminationInventory = captureTerminationProcessInventory(
 913                                 registration,
 914                                 terminationInventory,
 915                                 authenticatedWorkerExitExpected);
 916                     }
 917                     gracefulCloseMode &= !state.operatorStopRequested.get();
 918                     if (closeAcknowledged) {
 919                         parentTerminationSignalled = signalParentTermination(
 920                                 state,
 921                                 mutationStarted);
 922                     }
 923                     long processTerminationStartedAt = gracefulCloseMode
 924                             ? processTreeAccess.nanoTime()
 925                             : state.operatorStopStartedAtOr(terminationStartedAt);
 926                     boolean naturalTerminationExpected = gracefulCloseMode
 927                             && closeAcknowledged
 928                             && parentTerminationSignalled;
 929                     ProcessTreeCleanupOutcome outcome = terminateOwnedProcessTree(
 930                             registration.process(),
 931                             registration.processStartedAt(),
 932                             terminationInventory,
 933                             processTreeAccess,
 934                             cleanupStartedAt,
 935                             processTerminationStartedAt,
 936                             mutationStarted,
 937                             authenticatedWorkerExitExpected,
 938                             naturalTerminationExpected);
 939                     boolean operatorStopMode = !gracefulCloseMode
 940                             || state.operatorStopRequested.get();
 941                     long cancellationObservedAt = deadline(
 942                             processTerminationStartedAt,
 943                             outcome.cancellationLatency());
 944                     boolean operatorCancellationWithinBound = !operatorStopMode
 945                             || cancellationObservedAt <= deadline(
 946                                     state.operatorStopStartedAtOr(terminationStartedAt),
 947                                     IN_FLIGHT_CANCELLATION_MAX);
 948                     if ((!operatorStopMode && !authenticatedWorkerExitExpected)
 949                             || (closeAcknowledged && !parentTerminationSignalled)
 950                             || !outcome.identityComplete()
 951                             || !operatorCancellationWithinBound
 952                             || outcome.cleanupLatency().compareTo(PROCESS_TREE_CLEANUP_MAX) > 0
 953                             || outcome.residualOwnedProcessCount() != 0) {
 954                         throw new PlaywrightProviderException(
 955                                 PlaywrightProviderFailure.RUNTIME_FAILURE);
 956                     }
 957                 }
 958                 else {
 959                     closeQuietly(state.socket);
 960                     closeQuietly(state.server);
 961                 }
 962                 if (processTreeAccess.nanoTime()
 963                         > deadline(cleanupStartedAt, PROCESS_TREE_CLEANUP_MAX)) {
 964                     throw new PlaywrightProviderException(
 965                             PlaywrightProviderFailure.RUNTIME_FAILURE);
 966                 }
 967             }
 968             catch (RuntimeException | Error failure) {
 969                 cleanupFailure = failure;
 970                 PlaywrightProviderException reported = asProviderException(failure);
 971                 if (mutationStarted.get()) {
 972                     state.cleanupTerminalFailure = reported;
 973                 }
 974                 if (failure instanceof Error error) {
 975                     throw error;
 976                 }
